SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '1min';

DO $preflight$
BEGIN
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE (tool_name, version) IN (('submit_data_need_spec', 'v8'), ('run_python', 'v4'))) <> 2 THEN
        RAISE EXCEPTION 'Expected the previous tool versions (''submit_data_need_spec'', ''v8''), (''run_python'', ''v4'')';
    END IF;
    IF EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE (tool_name = 'submit_data_need_spec' AND version = 'v9') OR (tool_name = 'run_python' AND version = 'v5')) OR EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name IN ('read_conversation_memory')) THEN
        RAISE EXCEPTION 'The EXEC-C and EXEC-P5 tool versions are already registered';
    END IF;
END
$preflight$;

